"use strict";

/**
 * Per-repo configuration for the fleet checks: `.github/fleet-checks.json`,
 * optional (#1561).
 *
 * Source of truth: the operations repo's `scripts/fleet-checks/`; the shared
 * workflow repo's copy is generated by `publish.sh` and never hand-edited.
 *
 * A repo with one release stream and no exemptions needs no file at all: the
 * default is one stream, `default`, tagged `v*`, that every path ships in
 * (PM ruling on #1561, 2026-10-28). A repo shipping two things from one tree
 * declares each with its tag prefix and the paths that reach it, so a fragment
 * claiming a stream can be checked against what its PR touched.
 *
 *   {
 *     "changelog": {
 *       "streams": {
 *         "web":     { "tagPrefix": "v",         "paths": ["**"], "excludePaths": ["desktop/**"] },
 *         "desktop": { "tagPrefix": "desktop-v", "paths": ["desktop/**", "src/**"] }
 *       }
 *     },
 *     "deadPaths": {
 *       "exempt": [{ "glob": "docs/legacy/", "why": "frozen import of an old wiki" }],
 *       "linksResolveElsewhere": ["docs/template.md.tmpl"],
 *       "foreignNames": ["other-repo"]
 *     }
 *   }
 *
 * Validation refuses rather than defaults: an unknown key is a typo, and a
 * typo that is silently ignored reads as a check that ran (#1561).
 */

const fs = require("node:fs");
const path = require("node:path");

const CONFIG_PATH = ".github/fleet-checks.json";

const DEFAULT_STREAMS = { default: { tagPrefix: "v", paths: ["**"], excludePaths: [] } };

class ConfigError extends Error {}

function onlyKeys(obj, allowed, where) {
  if (obj === null || typeof obj !== "object" || Array.isArray(obj)) throw new ConfigError(`${where}: expected an object`);
  for (const k of Object.keys(obj)) {
    if (!allowed.includes(k)) throw new ConfigError(`${where}: unknown key "${k}" (allowed: ${allowed.join(", ")})`);
  }
}

function stringList(v, where) {
  if (v === undefined) return [];
  if (!Array.isArray(v) || v.some((x) => typeof x !== "string" || x === "")) {
    throw new ConfigError(`${where}: expected a list of non-empty strings`);
  }
  return v;
}

/** Validate a parsed config object and fill its defaults. */
function normalize(raw) {
  onlyKeys(raw, ["$comment", "changelog", "deadPaths"], CONFIG_PATH);
  const cl = raw.changelog ?? {};
  onlyKeys(cl, ["streams"], `${CONFIG_PATH} changelog`);
  let streams = DEFAULT_STREAMS;
  if (cl.streams !== undefined) {
    if (cl.streams === null || typeof cl.streams !== "object" || Array.isArray(cl.streams)) {
      throw new ConfigError(`${CONFIG_PATH} changelog.streams: expected an object of streams`);
    }
    const names = Object.keys(cl.streams);
    if (names.length === 0) throw new ConfigError(`${CONFIG_PATH} changelog.streams: declare at least one stream, or omit the key`);
    streams = {};
    const prefixes = new Map();
    for (const name of names) {
      if (!/^[a-z][a-z0-9-]*$/.test(name)) throw new ConfigError(`${CONFIG_PATH} stream "${name}": names are lowercase words`);
      if (name === "all" || name === "both") throw new ConfigError(`${CONFIG_PATH} stream "${name}": reserved as a \`ships:\` alias`);
      const s = cl.streams[name];
      const where = `${CONFIG_PATH} changelog.streams.${name}`;
      onlyKeys(s, ["tagPrefix", "paths", "excludePaths"], where);
      if (typeof s.tagPrefix !== "string" || s.tagPrefix === "" || /[\s*?[]/.test(s.tagPrefix)) {
        throw new ConfigError(`${where}.tagPrefix: a literal prefix such as "v" or "desktop-v"`);
      }
      // Two streams sharing a prefix would each claim the other's tags, so a
      // fragment would ship in whichever release sorted first.
      if (prefixes.has(s.tagPrefix)) throw new ConfigError(`${where}.tagPrefix: "${s.tagPrefix}" is also ${prefixes.get(s.tagPrefix)}'s`);
      prefixes.set(s.tagPrefix, name);
      const paths = stringList(s.paths, `${where}.paths`);
      if (paths.length === 0) throw new ConfigError(`${where}.paths: name the paths that ship in this stream ("**" for all)`);
      streams[name] = { tagPrefix: s.tagPrefix, paths, excludePaths: stringList(s.excludePaths, `${where}.excludePaths`) };
    }
    // One prefix starting another (`v` and `v2-`) is safe: a tag belongs to the
    // longest prefix a digit follows (changelog.js tagStream).
  }
  const dp = raw.deadPaths ?? {};
  onlyKeys(dp, ["exempt", "linksResolveElsewhere", "foreignNames", "comments"], `${CONFIG_PATH} deadPaths`);
  const exempt = (dp.exempt ?? []).map((e, i) => {
    const where = `${CONFIG_PATH} deadPaths.exempt[${i}]`;
    onlyKeys(e, ["glob", "why"], where);
    if (typeof e.glob !== "string" || !e.glob) throw new ConfigError(`${where}.glob: required`);
    // An exemption is a coverage gap; one with no reason cannot be told from a mistake (#867).
    if (typeof e.why !== "string" || e.why.trim().length < 8) throw new ConfigError(`${where}.why: say why this is not checked`);
    return { glob: e.glob, why: e.why };
  });
  if (dp.comments !== undefined && typeof dp.comments !== "boolean") throw new ConfigError(`${CONFIG_PATH} deadPaths.comments: true or false`);
  return {
    streams,
    deadPaths: {
      exempt,
      linksResolveElsewhere: new Set(stringList(dp.linksResolveElsewhere, `${CONFIG_PATH} deadPaths.linksResolveElsewhere`)),
      foreignNames: stringList(dp.foreignNames, `${CONFIG_PATH} deadPaths.foreignNames`),
      comments: dp.comments ?? true,
    },
  };
}

/** Load the repo's `.github/fleet-checks.json` from `root`, or the defaults when it has none. */
function loadConfig(root) {
  const file = path.join(root, CONFIG_PATH);
  if (!fs.existsSync(file)) return normalize({});
  let raw;
  try {
    raw = JSON.parse(fs.readFileSync(file, "utf8"));
  } catch (e) {
    throw new ConfigError(`${CONFIG_PATH}: not valid JSON (${e.message})`);
  }
  return normalize(raw);
}

module.exports = { CONFIG_PATH, DEFAULT_STREAMS, ConfigError, normalize, loadConfig };
